  for (const p of pages) {
    await page.goto(`http://127.0.0.1:4173/${p}.html`, { waitUntil: 'load' });
    const m = await page.evaluate(() => ({
      sw: document.documentElement.scrollWidth,
      cw: document.documentElement.clientWidth,
      overflow: [...document.querySelectorAll('body *')].filter(e => {
        const r = e.getBoundingClientRect();
        return r.right > document.documentElement.clientWidth + 1 || r.left < -1;
      }).slice(0,5).map(e => e.className || e.tagName),
    }));
    if (m.sw > m.cw) console.log(`OVERFLOW ${p} @${w}: scrollWidth=${m.sw} client=${m.cw}`, m.overflow);
  }
}
console.log('done');
await browser.close();
EOF
