  return {fontFamily: cs.fontFamily, fontWeight: cs.fontWeight, faces, widths,
    loaded: document.fonts.check('800 16px "Acme Sans"')};
});
console.log(JSON.stringify(d, null, 2));
await b.close();
EOF
